window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-04b552882e214dcc"]={"versions": [{"id": "FIG-04b552882e214dcc", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodellausschnitt zur Veranschaulichung der Granularität bei der Änderungserkennung (Modification Detection) im Kontext von AUTOSAR-Werkzeug-Interoperabilität (Model Differencing / Model Comparison).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Identifiable / A</strong>: Spezialisierung bzw. Ausprägung der Metaklasse <code>Identifiable</code>, farblich dunkel/gelb hervorgehoben zur Kennzeichnung einer erkannten Modifikation.\n</li><li><strong>B</strong>: Nicht-identifizierbare Metaklasse, die über eine Kompositionsbeziehung (schwarze Raute an <code>A</code>) als aggregierter Bestandteil von <code>A</code> definiert ist.\n</li><li><strong>B1</strong>: Nicht-identifizierbare Metaklasse, die über eine Kompositionsbeziehung (schwarze Raute an <code>B</code>) als geschachtelter/aggregierter Bestandteil von <code>B</code> definiert ist.\n</li><li><strong>Beziehungen</strong>: Strikte hierarchische Aggregationen (Kompositionen) <code>A</code> ➔ <code>B</code> ➔ <code>B1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne zeitliche Sequenz. Im Modellvergleichs- und Differenzierungsablauf führt eine Änderung an tief verschachtelten, nicht eigenständig identifizierbaren Elementen (<code>B1</code> oder <code>B</code>) rekursiv dazu, dass das übergeordnete <code>Identifiable</code>-Element <code>A</code> als modifiziert ausgewiesen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die fundamentale Granularität für die eigenständige Erkennung und Ausweisung von Modelländerungen ist das Element vom Typ <code>Identifiable</code>.\n</li><li>Elemente ohne eigene Identität (<code>non-identifiables</code>) können bei Werkzeugvergleichen nicht isoliert als eigenständige Differenz dargestellt werden, sondern markieren ihren besitzenden <code>Identifiable</code>-Wurzelknoten als geändert.\n</li><li>Werkzeughersteller müssen bei Differencing- und Merge-Funktionalitäten sicherstellen, dass transitive Änderungen in Aggregationshierarchien auf die umschließende identifizierbare Entität propagiert werden.\n</li></ul>"}, {"id": "FIG-c774490a72cabe29", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodellausschnitt zur Veranschaulichung der Granularität bei der Änderungserkennung (Modification Detection) im Kontext von AUTOSAR-Werkzeug-Interoperabilität (Model Differencing / Model Comparison).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Identifiable / A</strong>: Spezialisierung bzw. Ausprägung der Metaklasse <code>Identifiable</code>, farblich dunkel/gelb hervorgehoben zur Kennzeichnung einer erkannten Modifikation.\n</li><li><strong>B</strong>: Nicht-identifizierbare Metaklasse, die über eine Kompositionsbeziehung (schwarze Raute an <code>A</code>) als aggregierter Bestandteil von <code>A</code> definiert ist.\n</li><li><strong>B1</strong>: Nicht-identifizierbare Metaklasse, die über eine Kompositionsbeziehung (schwarze Raute an <code>B</code>) als geschachtelter/aggregierter Bestandteil von <code>B</code> definiert ist.\n</li><li><strong>Beziehungen</strong>: Strikte hierarchische Aggregationen (Kompositionen) <code>A</code> ➔ <code>B</code> ➔ <code>B1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne zeitliche Sequenz. Im Modellvergleichs- und Differenzierungsablauf führt eine Änderung an tief verschachtelten, nicht eigenständig identifizierbaren Elementen (<code>B1</code> oder <code>B</code>) rekursiv dazu, dass das übergeordnete <code>Identifiable</code>-Element <code>A</code> als modifiziert ausgewiesen wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Die fundamentale Granularität für die eigenständige Erkennung und Ausweisung von Modelländerungen ist das Element vom Typ <code>Identifiable</code>.\n</li><li>Elemente ohne eigene Identität (<code>non-identifiables</code>) können bei Werkzeugvergleichen nicht isoliert als eigenständige Differenz dargestellt werden, sondern markieren ihren besitzenden <code>Identifiable</code>-Wurzelknoten als geändert.\n</li><li>Werkzeughersteller müssen bei Differencing- und Merge-Funktionalitäten sicherstellen, dass transitive Änderungen in Aggregationshierarchien auf die umschließende identifizierbare Entität propagiert werden.\n</li></ul>"}], "trans": [{"from": "FIG-04b552882e214dcc", "to": "FIG-c774490a72cabe29", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
